src/ layout:
  src/index.ts          # bootstrap: McpServer + StdioServerTransport + registerAllTools + graceful shutdown
  src/registry.ts       # registerAllTools(server) -> calls each domain registrar
  src/tools/fs.ts       # registerFsTools(server)
  src/tools/git.ts      # registerGitTools(server)
  src/tools/exec.ts     # registerExecTools(server)  (IPC to Rust/Python skill servers)
  src/schemas/fs.ts     # Zod schemas, .strict().describe()
  src/services/ipc.ts   # child-process MCP client to skill servers, retry/timeout
  src/services/logger.ts# pino -> stderr
  src/types.ts          # z.infer-derived types
  src/constants.ts      # CHARACTER_LIMIT, tool-name prefixes

--- src/services/logger.ts (stderr ONLY) ---
import pino from 'pino';
// CRITICAL: destination fd 2 = stderr. stdout is JSON-RPC only.
export const log = pino({ level: process.env.LOG_LEVEL ?? 'info' }, pino.destination(2));

--- src/constants.ts ---
export const CHARACTER_LIMIT = 25_000;

--- src/utils/truncate.ts ---
export function truncate(text: string, offset = 0, limit = CHARACTER_LIMIT) {
  const slice = text.slice(offset, offset + limit);
  const has_more = offset + limit < text.length;
  return {
    text: slice + (has_more ? `\n\n[truncated: showing ${slice.length} of ${text.length} chars]` : ''),
    has_more,
    next_offset: has_more ? offset + limit : null,
    total: text.length,
  };
}

--- src/schemas/fs.ts (Zod .strict().describe()) ---
import { z } from 'zod';
export const FsReadInput = z.object({
  path: z.string().describe('Absolute path of the file to read.'),
  offset: z.number().int().min(0).default(0).describe('Character offset to start reading (for pagination).'),
  limit: z.number().int().min(1).default(25_000).describe('Max characters to return.'),
}).strict();
export type FsReadInput = z.infer<typeof FsReadInput>;

--- tool handler template (NEVER throw -> isError) ---
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { FsReadInput } from '../schemas/fs.js';
import { truncate } from '../utils/truncate.js';
import { log } from '../services/logger.js';
import { readFile } from 'node:fs/promises';

export function registerFsTools(server: McpServer) {
  server.registerTool(
    'fs_read_file',
    {
      title: 'Read file',
      description: 'Read a UTF-8 text file with character-offset pagination.',
      inputSchema: FsReadInput.shape,
      annotations: { readOnlyHint: true, openWorldHint: false },
    },
    async (args) => {
      try {
        const content = await readFile(args.path, 'utf8'); // async: never block the loop
        const { text, has_more, next_offset, total } = truncate(content, args.offset, args.limit);
        return {
          content: [{ type: 'text', text }],
          structuredContent: { has_more, next_offset, total },
        };
      } catch (err) {
        log.error({ err, path: args.path }, 'fs_read_file failed'); // stderr
        const msg = err instanceof Error ? err.message : String(err);
        return { content: [{ type: 'text', text: `Error reading ${args.path}: ${msg}` }], isError: true };
      }
    },
  );
}

--- src/registry.ts ---
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { registerFsTools } from './tools/fs.js';
import { registerGitTools } from './tools/git.js';
import { registerExecTools } from './tools/exec.js';
export function registerAllTools(server: McpServer) {
  registerFsTools(server);
  registerGitTools(server);
  registerExecTools(server);
}

--- src/index.ts (bootstrap + transport + graceful shutdown) ---
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { registerAllTools } from './registry.js';
import { log } from './services/logger.js';

async function main() {
  const server = new McpServer({ name: 'local-claw', version: '0.1.0' });
  registerAllTools(server);
  const transport = new StdioServerTransport();

  let shuttingDown = false;
  const shutdown = async (sig: string) => {
    if (shuttingDown) return; shuttingDown = true;
    log.info({ sig }, 'shutting down'); // stderr
    try { await server.close(); await transport.close(); } finally { process.exit(0); }
  };
  process.on('SIGINT', () => void shutdown('SIGINT'));
  process.on('SIGTERM', () => void shutdown('SIGTERM')); // RunPod/k8s scale-down
  process.on('uncaughtException', (e) => { log.fatal(e, 'uncaught'); void shutdown('uncaughtException'); });

  await server.connect(transport); // begins reading stdin / writing stdout (JSON-RPC only)
  log.info('local-claw MCP server ready on stdio'); // stderr
}
main().catch((e) => { log.fatal(e, 'fatal startup'); process.exit(1); });

Key rules encoded above: (1) logger -> fd 2 / stderr, never stdout; (2) every handler try/catch returns isError instead of throwing; (3) Zod .strict() + .describe() on every field, inputSchema passed as .shape; (4) truncate() enforces CHARACTER_LIMIT with has_more/next_offset; (5) async fs API so the event loop is never blocked; (6) SIGINT+SIGTERM graceful shutdown; (7) tools split per domain and wired through registerAllTools.
